<template>
    <DebugDisplay :debug="debug"></DebugDisplay>

    <VueModal :model-value="showModalOpen" :enableClose="false" modalClass="rounded max-w-4xl" :title="modalTitle" @update:modelValue="() => {}">
        <UAlert v-if="showerrors" variant="error">
            <div class="mb-4">
                A data integrity check has found invalid data in MyGrades. MyGrades cannot continue.
            </div>
            <div class="grid grid-cols-[minmax(0,2fr)_minmax(0,3fr)] gap-x-4 gap-y-2 items-center">
                <template v-for="error in errors" :key="errorKey(error)">
                    <div class="font-bold break-words">{{ error.itemname }}</div>
                    <div class="text-slate-600">
                        <template v-for="(part, index) in errorParts(error)" :key="index">
                            <strong v-if="part.bold" class="text-slate-800">{{ part.text }}</strong>
                            <template v-else>{{ part.text }}</template>
                        </template>
                    </div>
                </template>
            </div>
            <div class="flex justify-end items-center gap-4 mt-4">
                <div class="w-44">
                    <CleanupIntegrityButton :errors="errors" @cleaned="onCleanupComplete" />
                </div>
                <div class="w-44">
                    <MenuButton v-if="courseurl" :href="courseurl" :wide="true" iconName="MoveLeft">
                        {{ returnToCourseLabel }}
                    </MenuButton>
                </div>
            </div>
        </UAlert>
        <UAlert v-else-if="shownotices" variant="warning">
            <div class="mb-4">{{ noticeIntro }}</div>
            <ul class="list-disc pl-5 mb-4 space-y-1">
                <li v-for="notice in notices" :key="notice.itemname">
                    {{ notice.message }}
                </li>
            </ul>
            <div class="text-right">
                <UButton variant="primary" @click="continueSetup">{{ continueLabel }}</UButton>
            </div>
        </UAlert>
        <UAlert v-else>
            Setting up MyGrades and checking data integrity.
        </UAlert>
    </VueModal>
</template>

<script setup lang="ts">
    import { ref, onMounted, computed } from 'vue';
    import { storeToRefs } from 'pinia';
    import { useMstrings } from '@/stores/mstrings.js';
    import { moodleFetch } from '@/js/moodlefetch';
    import UAlert from './Common/UAlert.vue';
    import UButton from './Common/UButton.vue';
    import DebugDisplay from '@/components/Common/DebugDisplay.vue';
    import { useActivityTreeStore } from '../stores/activitytree.js';
    import { usePopulateTrees } from '@/js/setuptrees.ts';
    import CleanupIntegrityButton from './Capture/CleanupIntegrityButton.vue';
    import MenuButton from './Common/MenuButton.vue';
    import { useToast } from 'vue-toastification';

    interface iError {
        gradeitemid: number;
        itemname: string;
        error: string;
        errortype?: string;
        userid?: number;
        usernames?: string[];
    }

    interface iNotice {
        itemname: string;
        message: string;
    }

    const treestore = useActivityTreeStore();
    const populatetrees = usePopulateTrees();
    const mstringstore = useMstrings();
    const { mstrings } = storeToRefs(mstringstore);
    const toast = useToast();
    
    const debug = ref({});
    const errors = ref<iError[]>([]);
    const notices = ref<iNotice[]>([]);
    const showerrors = ref(false);
    const shownotices = ref(false);
    const isSettingUp = ref(true);
    const setupFinished = ref(false);
    const courseurl = ref('');

    const showModalOpen = computed(() => !setupFinished.value && (isSettingUp.value || showerrors.value || shownotices.value));

    const modalTitle = computed(() => {
        if (shownotices.value) {
            return mstrings.value.integrity_reassessment_notice_title || 'Reassessment updated';
        }
        return 'Setup and checking';
    });

    const noticeIntro = computed(() =>
        mstrings.value.integrity_reassessment_notice_intro
        || 'The gradebook structure has changed since reassessment was configured. MyGrades has automatically removed reassessment from the following categories:'
    );

    const continueLabel = computed(() => mstrings.value.integritycontinue || 'Continue');

    const returnToCourseLabel = computed(() => mstrings.value.integrity_return_to_course || 'Return to course');

    function showReassessmentNotices() {
        notices.value.forEach((notice) => {
            toast.warning(notice.message, { timeout: 15000 });
        });
    }

    async function continueSetup() {
        shownotices.value = false;
        isSettingUp.value = true;

        try {
            await populatetrees.populate();
            setupFinished.value = true;
            isSettingUp.value = false;
        } catch (error: any) {
            debug.value = error;
            console.error(error);
        }
    }

    onMounted(async () => {
        try {
            treestore.ready = false;

            const [result, courseinfo]: any[] = await Promise.all([
                moodleFetch('local_gugrades_check_integrity', {}),
                moodleFetch('local_gugrades_get_course_info', {}),
            ]);
            courseurl.value = courseinfo.url || '';
            errors.value = result.erroritems || [];
            notices.value = result.reassessmentnotices || [];

            if (notices.value.length > 0) {
                showReassessmentNotices();
            }

            if (errors.value.length > 0) {
                showerrors.value = true;
                isSettingUp.value = false;
                return;
            }

            if (notices.value.length > 0) {
                shownotices.value = true;
                isSettingUp.value = false;
                return;
            }

            await continueSetup();

        } catch (error: any) {
            debug.value = error;
            console.error(error);
        }
    });

    async function onCleanupComplete(payload: { cleaned: number; erroritems: iError[] }) {
        errors.value = payload.erroritems || [];

        if (errors.value.length === 0) {
            showerrors.value = false;
            if (notices.value.length > 0) {
                shownotices.value = true;
                return;
            }
            await continueSetup();
        }
    }

    function errorParts(error: iError): { text: string; bold: boolean }[] {
        const names = error.usernames || [];
        const joined = names.join(', ');
        const start = joined ? error.error.indexOf(joined) : -1;
        if (start === -1) {
            return [{ text: error.error, bold: false }];
        }

        const parts = [{ text: error.error.slice(0, start), bold: false }];
        names.forEach((name, index) => {
            if (index > 0) {
                parts.push({ text: ', ', bold: false });
            }
            parts.push({ text: name, bold: true });
        });
        parts.push({ text: error.error.slice(start + joined.length), bold: false });

        return parts;
    }

    function errorKey(error: iError) {
        return `item-${error.gradeitemid}-${error.errortype || 'default'}`;
    }
</script>
