<template>
    <DebugDisplay :debug="debug"></DebugDisplay>

    <MenuButton @click="recalculate_clicked" iconName="Sigma">
        {{ mstrings.recalculate }}
    </MenuButton>

    <VueModal v-model="showrecalculatemodal" :enableClose="false" modalClass="rounded max-w-3xl" :title="mstrings.recalculate">
        <div v-if="loading">
            <PleaseWait :staffuserid="props.staffuserid" progresstype="aggregate"></PleaseWait>
        </div>

        <div v-else>
            <UAlert class="mb-5" variant="info">{{ mstrings.recalculatehelp }}</UAlert>

            <div class="flex gap-2">
                <UButton variant="primary" @click="do_recalculate()">{{  mstrings.recalculate }}</UButton>
                <UButton variant="warning" @click="showrecalculatemodal = false">{{  mstrings.cancel }}</UButton>
            </div>
        </div>
    </VueModal>
</template>

<script setup lang="ts">
    import { ref } from 'vue';
    import { storeToRefs } from 'pinia';
    import { useMstrings } from '@/stores/mstrings.js';
    import { moodleFetch } from '@/js/moodlefetch';
    import { useToast } from "vue-toastification";
    import PleaseWait from '@/components/Common/PleaseWait.vue';
    import DebugDisplay from '@/components/Common/DebugDisplay.vue';
    import UButton from '../Common/UButton.vue';
    import UAlert from '../Common/UAlert.vue';
    import MenuButton from '../Common/MenuButton.vue';

    const showrecalculatemodal = ref(false);
    const loading = ref(false);
    const debug = ref({});
    const mstringstore = useMstrings();
    const { mstrings } = storeToRefs( mstringstore );

    const props = defineProps({
        categoryid: Number,
        staffuserid: Number,
    });

    const emits = defineEmits([
        'recalculated'
    ]);

    const toast = useToast();

    /**
     * Recalculate button has been clicked
     */
    function recalculate_clicked() {
        showrecalculatemodal.value = true;
    }

    /**
     * Perform recalculation
     */
    function do_recalculate() {

        loading.value = true;

        moodleFetch(
            'local_gugrades_recalculate',
            {
                gradecategoryid: props.categoryid,
            }
        )
        .then(() => {
            toast.success('Grades recalculated');
            loading.value = false;
            showrecalculatemodal.value = false;
            emits('recalculated');
        })
        .catch((error) => {
            window.console.error(error);
            showrecalculatemodal.value = false;
            debug.value = error;
        });
    }
</script>